it("restores an uncertain invoice after reload, explicitly replays the exact request and keeps one invoice",async()=>{
 const contextNode={isConnected:true,dataset:{workUser:"reviewer-1",workRevision:"revision-7",workCompany:"company-1",workAssignment:"finance-preparer-1",workAssignmentVersion:"3",workStale:"false"}},stored=new Map<string,string>(),storage={getItem:(key:string)=>stored.get(key)??null,setItem:(key:string,value:string)=>{stored.set(key,value);},removeItem:(key:string)=>{stored.delete(key);}},invoices=new Map<string,Record<string,unknown>>();
 vi.stubGlobal("document",{querySelector:()=>contextNode});vi.stubGlobal("window",Object.assign(new EventTarget(),{location:{origin:"https://console.example.test"}}));
 const input:FinanceInvoiceInput={partyId:"customer-original",invoiceDate:"2026-10-19",dueDate:"2026-11-18",currency:"THB",completionConfirmed:true,completionNote:"Original completed service evidence",lines:[{description:"Original completed service",quantity:"1",unitPrice:"100.00",taxBps:700}]},newerDraft={...input,completionNote:"Newer evidence added after the first request",lines:[{...input.lines[0]!,description:"Newer service description"}]};
 let loseFirstResponse=true,sendCount=0;
 const send=vi.fn(async(_url:RequestInfo|URL,_init?:RequestInit)=>{
  const init=_init!,key=new Headers(init.headers).get("Idempotency-Key")!,body=String(init.body),storedCommand=[...stored.entries()].find(([name])=>name.startsWith("erpx-finance-sales-invoice:")&&!name.endsWith(":draft"));sendCount++;
  expect(storedCommand,"command must be durable before the request is sent").toBeTruthy();expect(JSON.parse(storedCommand![1])).toMatchObject({owner:{userId:"reviewer-1",companyId:"company-1",assignmentId:"finance-preparer-1",revision:"revision-7",assignmentVersion:"3"},path:"invoices",input,body,key,uncertain:sendCount>1});
  let receipt=invoices.get(key);if(!receipt){receipt={id:`invoice-${key}-invoice`,status:"draft",version:1};invoices.set(key,receipt);}
  if(loseFirstResponse){loseFirstResponse=false;throw Error("The response was lost after commit.");}
  expect(body).toBe(JSON.stringify(input));return Response.json({data:receipt});
 });
 const create=()=>createFinanceSalesInvoiceCommands(()=>({base}),send as never,()=>storage as Storage,()=>"invoice-idempotency-key-1");
 const beforeReload=create();await expect(beforeReload.submit("invoices",input)).rejects.toThrow("response was lost");beforeReload.saveInvoiceDraft?.(newerDraft);
 const afterReload=create(),restored=afterReload.restoreInvoice?.();expect(restored).toEqual({pending:true,input,draft:newerDraft});expect(send).toHaveBeenCalledTimes(1);
 const posts=send.mock.calls.map(([,init])=>init);expect(posts[0]?.body).toBe(JSON.stringify(input));expect(new Headers(posts[0]?.headers).get("Idempotency-Key")).toBe("invoice-idempotency-key-1");
 const result=await afterReload.retry();expect(send).toHaveBeenCalledTimes(2);expect(result.unchanged()).toBe(false);expect(result.acknowledge()).toBe(true);expect(afterReload.pending()).toBe(false);expect(afterReload.restoreInvoice?.()).toEqual({pending:false,draft:newerDraft});expect(invoices.size).toBe(1);expect([...invoices.values()][0]?.id).toBe("invoice-invoice-idempotency-key-1-invoice");
 expect(send.mock.calls.map(([,init])=>[init?.body,new Headers(init?.headers).get("Idempotency-Key")])).toEqual([[JSON.stringify(input),"invoice-idempotency-key-1"],[JSON.stringify(input),"invoice-idempotency-key-1"]]);
});

it.each(["role","assignmentVersion","legacy"] as const)("quarantines a reloaded invoice when its saved owner has a changed %s",async change=>{
 const contextNode={isConnected:true,dataset:{workUser:"reviewer-1",workRevision:"revision-7",workCompany:"company-1",workAssignment:"finance-preparer-1",workAssignmentVersion:"3",workStale:"false"}},stored=new Map<string,string>(),storage={getItem:(key:string)=>stored.get(key)??null,setItem:(key:string,value:string)=>{stored.set(key,value);},removeItem:(key:string)=>{stored.delete(key);}},send=vi.fn(async()=>{throw Error("response lost");});
 vi.stubGlobal("document",{querySelector:()=>contextNode});vi.stubGlobal("window",Object.assign(new EventTarget(),{location:{origin:"https://console.example.test"}}));
 const input:FinanceInvoiceInput={partyId:"customer-original",invoiceDate:"2026-10-19",dueDate:"2026-11-18",currency:"THB",completionConfirmed:true,completionNote:"Original completed service evidence",lines:[{description:"Original completed service",quantity:"1",unitPrice:"100.00",taxBps:700}]},create=()=>createFinanceSalesInvoiceCommands(()=>({base}),send as never,()=>storage as Storage,()=>"invoice-idempotency-key-1");
 await expect(create().submit("invoices",input)).rejects.toThrow("response lost");if(change==="role")contextNode.dataset.workAssignment="finance-reviewer-2";else if(change==="assignmentVersion")contextNode.dataset.workAssignmentVersion="4";else for(const [key,raw] of stored){const old=JSON.parse(raw);old.version=1;delete old.owner.assignmentVersion;stored.set(key,JSON.stringify(old));}
 const retained=[...stored],recovered=create();expect(()=>recovered.restoreInvoice?.()).toThrow("not bound to this original owner");await expect(Promise.resolve().then(()=>recovered.retry())).rejects.toThrow("not bound to this original owner");expect([...stored]).toEqual(retained);expect(send).toHaveBeenCalledTimes(1);
});
